t('G2_08_fuzz_centinela_en_cada_cadena_del_paquete_nunca_llega_a_la_salida_publica', () => { let probes = 0; const leaves = (o, p, out) => { if (typeof o === 'string') out.push(p); else if (Array.isArray(o)) o.forEach((x, i) => leaves(x, p.concat(i), out)); else if (o && typeof o === 'object') Object.keys(o).forEach((k) => leaves(o[k], p.concat(k), out)); return out; }; const setAt = (o, p, v) => { let c = o; for (let i = 0; i < p.length - 1; i++) c = c[p[i]]; c[p[p.length - 1]] = v; };
  for (const name of ['base', 'fx_total_dop', 'net_consult', 'expired_condition', 'reclass15']) for (const part of ['public_dto', 'internal_view', 'context_evidence']) { const base = Q(name); if (!base[part]) continue; for (const p of leaves(base[part], [], [])) { const q = Q(name); const S = 'SYNTH_FUZZ_SENTINEL_' + (++probes); setAt(q[part], p, S); const r = ev(q, { actor: 'OPERATOR' }); const pv = JSON.stringify(K.publicView(r)); assert(!pv.includes(S), name + '.' + part + '.' + p.join('.') + ' → ' + pv); assert.notStrictEqual(r.B.verdict === 'LISTO' && JSON.stringify(r.B).includes(S), true); } }
  assert(probes > 100, 'fuzz con pocas sondas: ' + probes); });
