// ---- v2.0.6: cierre por catálogo de calculation_status / provider_amount_status de la vista interna (SCOPE-CORE1-KERNEL-INTERNAL-ENUM-HARDENING-20261024, A1–A12)
const SENT = 'SYNTH_PROBE_VALUE'; const CAT = require('../catalog'); const C = require('../contracts');
const withView = (name, f) => { const q = Q(name); f(q.internal_view); return q; }; // el servidor habría sellado el paquete con ese contenido: la huella NO enmascara al validador
const leak = (r, v) => JSON.stringify([r, K.publicView(r)]).includes(v);
const FIELDS = ['calculation_status', 'provider_amount_status'];
const BAD = [['ausente', undefined], ['null', null], ['booleano', true], ['numero', 0], ['objeto', {}], ['array', ['COMPLETE']], ['vacio', ''], ['espacios', '   '], ['minusculas', 'complete'], ['mixto', 'Complete'], ['con_espacio', 'COMPLETE '], ['desconocido', SENT]];
const setf = (v, f, x) => { if (x === undefined) delete v[f]; else v[f] = x; };
t('E01_sonda_centinela_en_ambos_campos_rechazada_sin_proyectar', () => { for (const actor of ['OPERATOR', 'AI_SELLER', undefined]) { const q = withView('base', (v) => { v.calculation_status = SENT; v.provider_amount_status = SENT; }); assert.strictEqual(C.validateInternalView(q.internal_view).ok, false); const r = evs(q, { actor }); assert.strictEqual(r.B.verdict, 'RECHAZADO'); has(r, 'INTERNAL_VIEW_SHAPE_INVALID'); notReady(r); assert.strictEqual(r.internal, null); assert(!leak(r, SENT)); } });
t('E02_cada_campo_se_rechaza_de_forma_independiente', () => { for (const f of FIELDS) { const q = withView('base', (v) => { v[f] = SENT; }); assert.strictEqual(C.validateInternalView(q.internal_view).detail, 'VIEW.' + f); const r = evs(q, { actor: 'OPERATOR' }); assert.strictEqual(r.B.verdict, 'RECHAZADO'); has(r, 'INTERNAL_VIEW_SHAPE_INVALID'); assert.strictEqual(r.internal, null); assert(!leak(r, SENT)); } });
t('E03_formas_invalidas_en_cada_campo_sin_excepcion_y_nunca_listo', () => { for (const f of FIELDS) for (const [n, x] of BAD) { const q = withView('base', (v) => setf(v, f, x)); let r; assert.doesNotThrow(() => { r = evs(q, { actor: 'OPERATOR' }); }, f + ':' + n); assert.strictEqual(r.B.verdict, 'RECHAZADO', f + ':' + n); notReady(r); assert.strictEqual(r.internal, null, f + ':' + n); if (typeof x === 'string' && x.trim()) assert(!leak(r, x), f + ':' + n); } });
t('E04_rechazo_con_motivo_fijo_y_sin_interpolar_el_valor_recibido', () => { const r1 = evs(withView('base', (v) => { v.calculation_status = 'ZZZ_UNIQUE_AAA'; }), { actor: 'OPERATOR' }), r2 = evs(withView('base', (v) => { v.calculation_status = 'ZZZ_UNIQUE_BBB'; }), { actor: 'OPERATOR' }); assert.deepStrictEqual(r1.B, r2.B); assert.deepStrictEqual(r1.B.reasons, ['INTERNAL_VIEW_SHAPE_INVALID']); assert(!JSON.stringify(r1).includes('ZZZ_UNIQUE')); assert.strictEqual(C.validateInternalView(withView('base', (v) => { v.provider_amount_status = 'ZZZ_UNIQUE_CCC'; }).internal_view).detail, 'VIEW.provider_amount_status'); });
t('E05_procedencia_catalogo_igual_al_censo_de_los_escenarios_del_adaptador_congelado', () => { const cs = new Set(), ps = new Set(); for (const q of Object.values(QS)) if (q.internal_view) { cs.add(q.internal_view.calculation_status); ps.add(q.internal_view.provider_amount_status); } assert.deepStrictEqual([...cs].sort(), [...CAT.CALCULATION_STATUS].sort()); assert.deepStrictEqual([...ps].sort(), [...CAT.PROVIDER_AMOUNT_STATUS].sort()); assert.deepStrictEqual([...CAT.CALCULATION_STATUS].sort(), ['COMPLETE', 'INCOMPLETE', 'INVALID', 'SOURCE_SUBTOTAL_ONLY']); assert.deepStrictEqual([...CAT.PROVIDER_AMOUNT_STATUS].sort(), ['ACCREDITED', 'NOT_ACCREDITED_CLIENT_FINAL', 'NOT_ACCREDITED_MIXED', 'NOT_ACCREDITED_NOT_EVALUATED', 'NOT_ACCREDITED_UNKNOWN']); });
t('E06_todos_los_estados_acreditados_se_conservan_y_los_errores_nunca_son_listo', () => { for (const [n, q0] of Object.entries(QS)) { if (!q0.internal_view) continue; const r = ev(Q(n), { actor: 'OPERATOR' }); assert.strictEqual(C.validateInternalView(q0.internal_view).ok, true, n); const st = q0.internal_view.calculation_status; if (n === 'enum_invalid_probe') { assert.deepStrictEqual(r.B.reasons, ['INPUT_INVALID']); notReady(r); continue; } /* fechas iguales: validateRequest ya la rechaza (v2.0.3 igual); la vista INVALID del adaptador sí es válida por contrato */  if (r.internal) { assert.strictEqual(r.internal.calculation_status, st, n); assert.strictEqual(r.internal.provider_amount_status, q0.internal_view.provider_amount_status, n); } if (st !== 'COMPLETE') { assert.notStrictEqual(r.B.verdict, 'LISTO', n); notReady(r); assert.strictEqual(r.B.verdict, 'CONSULTAR', n); assert(r.internal && r.internal.calculation_status === st, n); } } });
t('E07_estados_de_error_incompleto_e_invalido_conservan_semantica_de_consulta_publica', () => { for (const [n, st, rs] of [['enum_incomplete_no_rate', 'INCOMPLETE', 'CORE1_NO_RATE_FOR_DATES'], ['enum_basis_unknown', 'SOURCE_SUBTOTAL_ONLY', 'CORE1_PENDING_REVIEW']]) { const r = ev(Q(n), { actor: 'AI_SELLER' }); assert.strictEqual(r.internal.calculation_status, st); assert.deepStrictEqual(r.B.reasons, [rs]); assert.strictEqual(K.publicView(r).price_readiness.verdict, 'CONSULTAR'); } const inv = Q('enum_invalid_probe'); assert.strictEqual(inv.internal_view.calculation_status, 'INVALID'); assert.strictEqual(C.validateInternalView(inv.internal_view).ok, true); });
t('E08_misma_entrada_valida_de_v2_0_3_da_el_mismo_resultado_en_v2_0_4', () => { const K3 = require('../../kernel-v2.0.3'); const H3 = J(path.join(root, 'kernel-v2.0.3/fixtures/hotel_synthetic.json')); const Q3 = J(path.join(root, 'kernel-v2.0.3/fixtures/paired-quotes.json')).quotes; assert.strictEqual(Q3.length, 11); for (const q of Q3) for (const actor of [undefined, 'OPERATOR', 'AI_SELLER']) { const c = { now: NOW, fx_authorities: AUTH, actor }; const a = K3.evaluate(H3, q.request, quoteOf(clone(q)), c), b = K.evaluate(hotel, q.request, quoteOf(clone(q)), c); const strip = (r) => Object.assign({}, r, { kernel_version: 0, supersedes: 0 }); assert.deepStrictEqual(strip(b), strip(a), q.name); assert.deepStrictEqual(Object.assign({}, K.publicView(b), { kernel_version: 0 }), Object.assign({}, K3.publicView(a), { kernel_version: 0 }), q.name); } });
t('E09_sonda_original_reproduce_en_v2_0_3_y_la_misma_entrada_se_rechaza_en_v2_0_4', () => { const pr = cp.spawnSync(process.execPath, [path.join(root, 'kernel-probes/KERNEL-V2.0.3-INTERNAL-VIEW-ENUM-PROBE/probe.js')], { encoding: 'utf8' }); assert.strictEqual(pr.status, 0); const o = JSON.parse(pr.stdout); assert.strictEqual(o.hypothesis_reproduced, true); assert.strictEqual(o.kernel_B_verdict, 'LISTO'); const q = withView('base', (v) => { v.calculation_status = o.sent; v.provider_amount_status = o.sent; }); const r = evs(q, { actor: 'OPERATOR' }); assert.strictEqual(r.B.verdict, 'RECHAZADO'); assert.strictEqual(r.internal, null); });
t('E10_rechazo_semantico_con_huella_correcta_y_no_confundido_con_huella_incorrecta', () => { let q = withView('base', (v) => { v.calculation_status = SENT; }); assert.strictEqual(q.context_evidence.evaluation_snapshot.internal_view_digest, digest(Q('base').internal_view)); const stale = ev(q, { actor: 'OPERATOR' }); has(stale, 'INTERNAL_VIEW_SHAPE_INVALID'); const sealed = evs(withView('base', (v) => { v.calculation_status = SENT; }), { actor: 'OPERATOR' }); assert.deepStrictEqual(sealed.B.reasons, ['INTERNAL_VIEW_SHAPE_INVALID']); assert.strictEqual(sealed.A.verdict, 'COMPLETO'); q = Q('base'); q.internal_view.calculation_status = 'INCOMPLETE'; const dig = ev(q, { actor: 'OPERATOR' }); assert.notDeepStrictEqual(dig.B.reasons, ['INTERNAL_VIEW_SHAPE_INVALID']); assert(dig.B.reasons.some((c) => /INTERNAL_VIEW|SNAPSHOT/.test(c)) , JSON.stringify(dig.B)); notReady(dig); });
t('E11_vista_ausente_conserva_el_comportamiento_de_v2_0_3', () => { for (const x of [undefined, null]) { const q = Q('base'); if (x === undefined) delete q.internal_view; else q.internal_view = null; const r = ev(q); assert.notStrictEqual(r.B.verdict, 'LISTO'); has(r, 'FX_APPLICABILITY_UNVERIFIED'); } });
t('E12_vista_de_motor_previo_sin_estados_ya_se_rechazaba_y_sigue_rechazandose', () => { const q = withView('base', (v) => { for (const k of Object.keys(v)) delete v[k]; v.view_version = 'CORE1-PRICE-INTERNAL-VIEW-v1.1.1'; v.pre_engine_status = 'FX_DRIFT'; v.provider_amount = null; v.source_subtotal = null; v.final_price_confirmed = null; v.collection_allowed = false; }); const r = evs(q, { actor: 'OPERATOR' }); assert.strictEqual(r.B.verdict, 'RECHAZADO'); });
t('E13_version_declarada_candidata_y_v2_0_3_sin_cambios', () => { assert.strictEqual(K.KERNEL_VERSION, 'HOTEL-INTEGRITY v2.0.6-candidate'); const md = fs.readFileSync(path.join(root, 'kernel-v2.0.3/MANIFEST.sha256'), 'utf8').trim().split('\n'); assert(md.length > 10); for (const l of md) { const m = l.match(/^([0-9a-f]{64})\s+\*?(.+)$/); assert(m, l); assert.strictEqual(crypto.createHash('sha256').update(fs.readFileSync(path.join(root, 'kernel-v2.0.3', m[2].replace(/^\.\//, '')))).digest('hex'), m[1], m[2]); } });

// ---- addendum A5 (ADDENDUM-CORE1-KERNEL-A5-COHERENCE-20261024): PRICE_REFERENCE + {SOURCE_SUBTOTAL_ONLY, INCOMPLETE, INVALID} es contradictorio
const NOPRICE = ['SOURCE_SUBTOTAL_ONLY', 'INCOMPLETE', 'INVALID']; const COMPLETE_PROPOSAL = 'PREPARACION_COMPLETA_SUJETA_A_AUTORIDAD';
const rejectedA5 = (r) => { assert.strictEqual(r.B.verdict, 'RECHAZADO', JSON.stringify(r.B)); assert.deepStrictEqual(r.B.reasons, ['INTERNAL_VIEW_SHAPE_INVALID']); assert.strictEqual(r.B.reference_total, undefined); assert.notStrictEqual(r.C.proposal, COMPLETE_PROPOSAL); assert.strictEqual(r.internal, null); };
t('A5R1_dto_de_precio_con_cada_estado_sin_precio_y_huella_correcta_se_rechaza', () => { for (const st of NOPRICE) { const q = withView('base', (v) => { v.calculation_status = st; }); assert.strictEqual(q.public_dto.status, 'PRICE_REFERENCE'); const r = evs(q, { actor: 'OPERATOR' }); rejectedA5(r); } });
t('A5R2_la_proteccion_no_depende_del_actor_ni_de_la_vista_publica', () => { for (const st of NOPRICE) for (const actor of ['OPERATOR', 'AI_SELLER', undefined]) { const r = evs(withView('base', (v) => { v.calculation_status = st; }), { actor }); rejectedA5(r); const pv = JSON.stringify(K.publicView(r)); assert(!pv.includes('200.00'), st + actor); assert(!pv.includes(COMPLETE_PROPOSAL), st + actor); assert.strictEqual(K.publicView(r).price_readiness.reference_total, undefined); assert(!JSON.stringify(r).includes('calculation_status'), 'el valor recibido no se interpola: ' + st); } });
t('A5R3_control_complete_conserva_el_caso_positivo_y_no_se_rechazan_todos_los_precios', () => { for (const n of Object.keys(QS)) { const q = QS[n]; if (q.public_dto.status !== 'PRICE_REFERENCE') continue; assert.strictEqual(q.internal_view.calculation_status, 'COMPLETE', n); const r = ev(Q(n), { actor: 'OPERATOR' }); assert.strictEqual(r.B.verdict, 'LISTO', n + JSON.stringify(r.B)); assert(r.B.reference_total, n); } assert.strictEqual(ev(Q('base')).B.reference_total.amount, '200.00'); });
t('A5R4_paquetes_geniunos_de_consulta_y_error_conservan_semantica_y_catalogos_completos', () => { assert.strictEqual(CAT.CALCULATION_STATUS.length, 4); assert.strictEqual(CAT.PROVIDER_AMOUNT_STATUS.length, 5); for (const st of NOPRICE) assert(CAT.CALCULATION_STATUS.includes(st)); const exp = { net_consult: ['CORE1_PENDING_REVIEW'], enum_basis_unknown: ['CORE1_PENDING_REVIEW'], enum_mixed_probe: ['CORE1_PENDING_REVIEW'], enum_incomplete_no_rate: ['CORE1_NO_RATE_FOR_DATES'], enum_incomplete_placeholder: ['CORE1_NO_RATE_FOR_DATES'], enum_invalid_probe: ['INPUT_INVALID'] }; for (const [n, reasons] of Object.entries(exp)) { const q = QS[n]; assert.notStrictEqual(q.public_dto.status, 'PRICE_REFERENCE', n); const r = ev(Q(n), { actor: 'OPERATOR' }); assert.deepStrictEqual(r.B.reasons, reasons, n); } });
t('A5R7_incoherencia_con_huella_correcta_se_distingue_de_integridad_con_huella_incorrecta', () => { const unsealed = ev(withView('base', (v) => { v.calculation_status = 'INCOMPLETE'; }), { actor: 'OPERATOR' }); assert.deepStrictEqual(unsealed.B.reasons, ['SNAPSHOT_INTERNAL_VIEW_MISMATCH']); assert(!unsealed.B.reasons.includes('INTERNAL_VIEW_SHAPE_INVALID'), JSON.stringify(unsealed.B)); assert.strictEqual(unsealed.B.verdict, 'RECHAZADO'); const sealed = evs(withView('base', (v) => { v.calculation_status = 'INCOMPLETE'; }), { actor: 'OPERATOR' }); assert.deepStrictEqual(sealed.B.reasons, ['INTERNAL_VIEW_SHAPE_INVALID']); });
t('A5R9_acreditado_con_precio_de_referencia_antes_abierto_ahora_cerrado_por_R2_y_consultas_y_vista_ausente_intactas', () => { const acc = withView('base', (v) => { v.provider_amount_status = 'ACCREDITED'; }); const r = evs(acc); assert.strictEqual(r.B.verdict, 'RECHAZADO'); assert.deepStrictEqual(r.B.reasons, ['INTERNAL_VIEW_SHAPE_INVALID']); const sh = Q('net_consult'); assert.strictEqual(sh.public_dto.status, 'CONSULT'); assert.strictEqual(ev(sh).B.verdict, 'CONSULTAR'); const none = Q('base'); delete none.internal_view; assert.notDeepStrictEqual(ev(none).B.reasons, ['INTERNAL_VIEW_SHAPE_INVALID']); });

// ---- v2.0.6: coherencia base ↔ estado ↔ importe del proveedor ↔ DTO (MANDATE-CORE1-PROVIDER-AMOUNT-COHERENCE-20261024; R1–R4; PA1–PA10)
const K4 = require('../../kernel-v2.0.4'); const H4 = hotel; const SHA_FIXTURE = 'cbfac24e6849d74fb425c4c12873dcd5a38bb5b2dff0b4c4135cd6c4f3035c44';
const NETPA = (amt, ccy) => ({ amount: amt || '200.00', currency: ccy || 'USD', label: 'INTERNAL_PROVIDER_AMOUNT_NOT_CLIENT_PRICE', accredited_by: 'price_basis=NET_PROVIDER on every used row' });
const PCASES = { // P01–P07 del Curator (§5 de la propuesta), construidos sobre los fixtures genuinos
  P01: ['base', (v) => { v.provider_amount_status = 'ACCREDITED'; }, 'LISTO'],
  P02: ['base', (v) => { v.provider_amount_status = 'ACCREDITED'; v.source_basis = { status: 'NET_PROVIDER', bases: ['NET_PROVIDER'] }; v.source_subtotal.basis = 'NET_PROVIDER'; v.provider_amount = NETPA(); for (const x of v.traceability) x.price_basis = 'NET_PROVIDER'; }, 'LISTO'],
  P03: ['base', (v) => { v.provider_amount = NETPA('9999.00'); }, 'LISTO'],
  P04: ['net_consult', (v) => { v.provider_amount = null; }, 'CONSULTAR'],
  P05: ['net_consult', (v) => { v.provider_amount.amount = '9999.00'; }, 'CONSULTAR'],
  P06: ['base', (v) => { delete v.source_basis; }, 'LISTO'],
  P07: ['net_consult', (v) => { v.source_basis = { status: 'CLIENT_FINAL', bases: ['CLIENT_FINAL'] }; }, 'CONSULTAR'] };
const SHAPE = ['INTERNAL_VIEW_SHAPE_INVALID'];
const rejectedPA = (r, tag) => { assert.strictEqual(r.B.verdict, 'RECHAZADO', tag + JSON.stringify(r.B)); assert.deepStrictEqual(r.B.reasons, SHAPE, tag); assert.strictEqual(r.B.reference_total, undefined, tag); assert.notStrictEqual(r.C.proposal, COMPLETE_PROPOSAL, tag); assert.strictEqual(r.internal, null, tag); };
const evK = (Kx, q, ctx, h) => Kx.evaluate(h || hotel, q.request, quoteOf(q), Object.assign({ now: NOW, fx_authorities: AUTH }, ctx));
t('PA1_los_16_paquetes_legitimos_se_regeneran_identicos_y_conservan_semantica', () => { const tmp = path.join(require('os').tmpdir(), 'pa1-' + process.pid + '.json'); const g = cp.spawnSync('python3', ['-I', '-B', path.join(__dirname, '..', 'tools', 'gen_paired_quotes_v206.py.inert'), path.join(root, 'core1-price/versions'), tmp], { encoding: 'utf8', env: Object.assign({}, process.env, { PYTHONDONTWRITEBYTECODE: '1' }) }); assert.strictEqual(g.status, 0, g.stderr); const bytes = fs.readFileSync(tmp); fs.unlinkSync(tmp); assert.strictEqual(crypto.createHash('sha256').update(bytes).digest('hex'), SHA_FIXTURE); assert.strictEqual(crypto.createHash('sha256').update(fs.readFileSync(path.join(__dirname, '..', 'fixtures', 'paired-quotes.json'))).digest('hex'), SHA_FIXTURE); assert.strictEqual(Object.keys(QS).length, 16); const strip = (r) => Object.assign({}, r, { kernel_version: 0, supersedes: 0 }); for (const [n, q0] of Object.entries(QS)) for (const actor of [undefined, 'OPERATOR', 'AI_SELLER']) { const a = evK(K4, Q(n), { actor }, H4), b = evK(K, Q(n), { actor }); assert.deepStrictEqual(strip(b), strip(a), n + ':' + actor); } });
t('PA2_p01_p07_son_controles_historicos_en_v2_0_4_y_se_rechazan_en_v2_0_5_con_digest_correcto', () => { for (const [id, [name, f, hist]] of Object.entries(PCASES)) { const q = withView(name, f); const h = evK(K4, seal(clone(q)), { actor: 'OPERATOR' }, H4); assert.strictEqual(h.B.verdict, hist, id + ' historico v2.0.4 ' + JSON.stringify(h.B)); const r = evs(clone(q), { actor: 'OPERATOR' }); rejectedPA(r, id); } });
t('PA3_operator_ai_seller_y_publico_sin_total_preparacion_ni_objeto_interno', () => { for (const [id, [name, f]] of Object.entries(PCASES)) for (const actor of ['OPERATOR', 'AI_SELLER', undefined]) { const r = evs(withView(name, f), { actor }); rejectedPA(r, id + actor); const w = JSON.stringify([r, K.publicView(r)]); assert(!w.includes('9999.00'), id + actor); assert(!w.includes('provider_amount'), id + actor); assert(!w.includes(COMPLETE_PROPOSAL.replace(/^/, '"proposal":"')), id + actor); assert.strictEqual(K.publicView(r).price_readiness.reference_total, undefined); } });
const mut = (name, f) => withView(name, f);
t('PA4_formas_y_contradicciones_de_base_estado_importe_y_moneda', () => { const SENTV = 'SYNTH_LEAK_9'; const cases = []; const add = (n, name, f) => cases.push([n, name, f]);
  for (const [n, x] of [['ausente', undefined], ['null', null], ['cadena', SENTV], ['numero', 3], ['array', []], ['vacio', {}], ['clave_extra', { status: 'CLIENT_FINAL', bases: ['CLIENT_FINAL'], extra: SENTV }], ['sin_bases', { status: 'CLIENT_FINAL' }], ['sin_status', { bases: ['CLIENT_FINAL'] }], ['status_desconocido', { status: SENTV, bases: ['CLIENT_FINAL'] }], ['status_minuscula', { status: 'client_final', bases: ['CLIENT_FINAL'] }], ['bases_no_array', { status: 'CLIENT_FINAL', bases: 'CLIENT_FINAL' }], ['bases_no_cadena', { status: 'CLIENT_FINAL', bases: [1] }], ['bases_duplicadas', { status: 'MIXED', bases: ['A', 'A'] }], ['client_con_net', { status: 'CLIENT_FINAL', bases: ['NET_PROVIDER'] }], ['client_con_dos', { status: 'CLIENT_FINAL', bases: ['CLIENT_FINAL', 'X'] }], ['client_vacio', { status: 'CLIENT_FINAL', bases: [] }], ['mixed_con_una', { status: 'MIXED', bases: ['X'] }], ['unknown_con_client', { status: 'UNKNOWN', bases: ['CLIENT_FINAL'] }], ['unknown_con_dos', { status: 'UNKNOWN', bases: ['X', 'Y'] }], ['notevaluated_con_base', { status: 'NOT_EVALUATED', bases: ['CLIENT_FINAL'] }]]) add('source_basis:' + n, 'base', (v) => setf(v, 'source_basis', x));
  for (const [n, x] of [['ausente', undefined], ['undefined', undefined], ['cadena', SENTV], ['numero', 0], ['objeto', NETPA()], ['array', []]]) add('provider_amount_cliente:' + n, 'base', (v) => setf(v, 'provider_amount', x));
  for (const base of ['base', 'net_consult', 'enum_basis_unknown', 'enum_mixed_probe', 'enum_incomplete_no_rate']) for (const bad of CAT.PROVIDER_AMOUNT_STATUS) { add('estado_vs_base:' + base + ':' + bad, base, (v) => { if (v.provider_amount_status !== bad) v.provider_amount_status = bad; else v.provider_amount_status = SENTV; }); }
  add('net:sin_provider_amount', 'net_consult', (v) => { delete v.provider_amount; }); add('net:provider_amount_cadena', 'net_consult', (v) => { v.provider_amount = SENTV; }); add('net:clave_extra', 'net_consult', (v) => { v.provider_amount.extra = SENTV; }); add('net:sin_label', 'net_consult', (v) => { delete v.provider_amount.label; }); add('net:label_distinto', 'net_consult', (v) => { v.provider_amount.label = SENTV; }); add('net:accredited_by_distinto', 'net_consult', (v) => { v.provider_amount.accredited_by = SENTV; });
  add('net:importe_distinto_del_subtotal', 'net_consult', (v) => { v.provider_amount.amount = '9999.00'; }); add('net:importe_con_formato_invalido', 'net_consult', (v) => { v.provider_amount.amount = SENTV; }); add('net:moneda_distinta', 'net_consult', (v) => { v.provider_amount.currency = 'DOP'; }); add('net:moneda_invalida', 'net_consult', (v) => { v.provider_amount.currency = SENTV; });
  add('net:subtotal_ausente', 'net_consult', (v) => { v.source_subtotal = null; }); add('net:subtotal_con_otra_base', 'net_consult', (v) => { v.source_subtotal.basis = 'CLIENT_FINAL'; });
  for (const nm of ['base', 'enum_basis_unknown', 'enum_mixed_probe']) add('subtotal_con_otra_base:' + nm, nm, (v) => { v.source_subtotal.basis = SENTV; });
  add('notevaluated:subtotal_presente', 'enum_incomplete_no_rate', (v) => { v.source_subtotal = { amount: '1.00', currency: 'USD', basis: 'NOT_EVALUATED' }; }); add('notevaluated:provider_amount_presente', 'enum_incomplete_no_rate', (v) => { v.provider_amount = NETPA(); }); add('notevaluated:subtotal_ausente_clave', 'enum_incomplete_no_rate', (v) => { delete v.source_subtotal; });
  add('mixed:provider_amount_presente', 'enum_mixed_probe', (v) => { v.provider_amount = NETPA(); }); add('unknown:provider_amount_presente', 'enum_basis_unknown', (v) => { v.provider_amount = NETPA(); });
  add('precio_referencia:sin_subtotal', 'base', (v) => { v.source_subtotal = null; }); add('precio_referencia:subtotal_no_objeto', 'base', (v) => { v.source_subtotal = SENTV; });
  for (const [nm, st, bs] of [['net_consult', 'NET_PROVIDER', ['CLIENT_FINAL']], ['net_consult', 'NET_PROVIDER', ['NET_PROVIDER', 'X']], ['net_consult', 'NET_PROVIDER', []], ['enum_incomplete_no_rate', 'NOT_EVALUATED', ['X']], ['enum_incomplete_no_rate', 'NOT_EVALUATED', ['CLIENT_FINAL']], ['enum_mixed_probe', 'MIXED', ['X']], ['enum_mixed_probe', 'MIXED', ['A', 'A']], ['enum_mixed_probe', 'MIXED', []], ['enum_basis_unknown', 'UNKNOWN', ['CLIENT_FINAL']], ['enum_basis_unknown', 'UNKNOWN', ['NET_PROVIDER']], ['enum_basis_unknown', 'UNKNOWN', ['X', 'Y']], ['enum_basis_unknown', 'UNKNOWN', []]]) add('bases_consulta_coherente_con_estado:' + nm + ':' + JSON.stringify(bs), nm, (v) => { v.source_basis = { status: st, bases: bs }; });
  assert(cases.length >= 70, 'casos: ' + cases.length);
  for (const [n, name, f] of cases) { const q = mut(name, f); let r; assert.doesNotThrow(() => { r = evs(q, { actor: 'OPERATOR' }); }, n); rejectedPA(r, n); assert(!JSON.stringify([r, K.publicView(r)]).includes(SENTV), n); const r2 = evs(mut(name, f), { actor: undefined }); assert.deepStrictEqual(r2.B, r.B, n); } });
